structures.forEach(s=>{for(let y=s.y;y<s.y+s.h;y++)for(let x=s.x;x<s.x+s.w;x++){if(x<SIZE&&y<SIZE)grid[y][x]=s.c+10}});
// Keep key interaction points reachable through the cross streets.
items.forEach(o=>openCell(Math.round(o.x),Math.round(o.y)));evidence.forEach(o=>openCell(Math.round(o.x),Math.round(o.y)));persons.forEach(o=>openCell(Math.round(o.x),Math.round(o.y)));
const wallColors={1:'#333a35',2:'#493e37',3:'#474744',4:'#465044',5:'#3c4542',6:'#49423b',7:'#41493f',8:'#3a4342',9:'#484238',11:'#4b4540',12:'#605448',13:'#55534b',14:'#4a514b',15:'#4b4c42',16:'#535044',17:'#54514a',18:'#414b46',19:'#514a40'};
let w=0,h=0,pxRatio=1,keys={},last=performance.now(),elapsed=0,toastTimer=0,nearest=null,activePanel='case',caseTab='evidence',pointer=false,mouseLook=0,downTouch=null;
function resize(){pxRatio=Math.min(devicePixelRatio||1,1.5);w=Math.floor(innerWidth*pxRatio);h=Math.floor(innerHeight*pxRatio);canvas.width=w;canvas.height=h}
addEventListener('resize',resize);resize();
function wallAt(x,y){if(x<0||y<0||x>=SIZE||y>=SIZE)return 1;return grid[Math.floor(y)][Math.floor(x)]}
function collides(x,y){return wallAt(x-.18,y-.18)>0||wallAt(x+.18,y-.18)>0||wallAt(x-.18,y+.18)>0||wallAt(x+.18,y+.18)>0}
function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2500)}
function save(slot=0,quiet=false){const data={version:1,world,player,flags,evidence,persons,items};try{localStorage.setItem(SAVE_PREFIX+slot,JSON.stringify(data));localStorage.setItem(SAVE_PREFIX+'active',String(slot));if(!quiet)say(`FIELD NOTES SAVED · SLOT ${slot+1}`)}catch(e){if(!quiet)say('SAVE FAILED — STORAGE UNAVAILABLE')}}
function load(slot=0){try{let raw=localStorage.getItem(SAVE_PREFIX+slot);if(!raw)return false;const d=JSON.parse(raw);if(!d||d.version!==1)return false;Object.assign(world,d.world||{});Object.assign(player,d.player||{});Object.assign(flags,d.flags||{});for(const arr of [evidence,persons,items]){const saved=d[arr===evidence?'evidence':arr===persons?'persons':'items']||[];arr.forEach(a=>{let b=saved.find(x=>x.id===a.id);if(b)Object.assign(a,b)})}return true}catch(e){return false}}
function nearestPlace(x=player.x,y=player.y){return locations.reduce((best,l)=>{let d=Math.hypot(l.x-x,l.y-y);return d<best.d?{l,d}:best},{l:locations[0],d:999}).l}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function objective(){let title,txt,count;if(!flags.sceneSecured){title='Search the scene. The rain is washing away the night.';count=evidence.filter(e=>['fiber','key','testament'].includes(e.id)&&e.found).length;ui.location.textContent='OLD MERCY CHAPEL · GROUNDS'}else if(!flags.analyzed){title='Take the evidence to Gloamwood Police. Request a forensic comparison.';count=0;ui.location.textContent=nearestPlace().name}else if(!flags.interviewedMara){title='Find the night-shift witness at the Nightjar Diner.';count=0;ui.location.textContent=nearestPlace().name}else if(!flags.sectFound){title='The archive may explain the repeated sunburst. Follow the records.';count=0;ui.location.textContent=nearestPlace().name}else if(!flags.warrant){title='Build a case. Separate rumor from proof, then request a warrant.';count=0;ui.location.textContent=nearestPlace().name}else{title='Return to Old Mercy. Jonah Bell is waiting beneath the chapel.';count=0;ui.location.textContent=nearestPlace().name}ui.objective.textContent=title;ui.progressText.textContent=count?`${count} / 3`:flags.warrant?'WARRANT ISSUED':'';ui.progressBar.style.width=`${count/3*100}%`;document.getElementById('evidenceCount').textContent=evidence.filter(e=>e.found).length;document.getElementById('healthNum').textContent=Math.round(player.health);document.getElementById('healthBar').style.width=`${player.health}%`;document.getElementById('stressNum').textContent=Math.round(player.stress);document.getElementById('stressBar').style.width=`${player.stress}%`}
function draw(){if(!w||!h)return;const sw=Math.max(180,Math.floor(w/2)),sh=Math.max(120,Math.floor(h/2)),image=ctx.createImageData(sw,sh),data=image.data;
 const horizon=sh*.49+Math.sin(player.angle*1.6)*2,dirX=Math.cos(player.angle),dirY=Math.sin(player.angle),planeX=-dirY*.66,planeY=dirX*.66;
 for(let x=0;x<sw;x++){
  let cameraX=2*x/sw-1,rayX=dirX+planeX*cameraX,rayY=dirY+planeY*cameraX,mapX=Math.floor(player.x),mapY=Math.floor(player.y),deltaX=Math.abs(1/(rayX||.00001)),deltaY=Math.abs(1/(rayY||.00001)),stepX,stepY,sideX,sideY;
  if(rayX<0){stepX=-1;sideX=(player.x-mapX)*deltaX}else{stepX=1;sideX=(mapX+1-player.x)*deltaX}if(rayY<0){stepY=-1;sideY=(player.y-mapY)*deltaY}else{stepY=1;sideY=(mapY+1-player.y)*deltaY}
  let side=0,hit=0,wall=1;for(let i=0;i<60&&!hit;i++){if(sideX<sideY){sideX+=deltaX;mapX+=stepX;side=0}else{sideY+=deltaY;mapY+=stepY;side=1}wall=wallAt(mapX,mapY);if(wall)hit=1}let distWall=side===0?sideX-deltaX:sideY-deltaY;distWall=Math.max(.16,distWall);let lineH=Math.min(sh*2,sh/distWall),start=Math.max(0,Math.floor(horizon-lineH*.52)),end=Math.min(sh,Math.floor(horizon+lineH*.56));let base=wallColors[wall]||'#45483f';if(wall>=11)base=wallColors[wall-10]||'#45483f';let rgb=hex(base),shade=Math.max(.17,1-distWall/16)*(side===1?.79:1),texture=((mapX*19+mapY*37+wall*11)%7)*.016;
  for(let y=0;y<sh;y++){let idx=(y*sw+x)*4,rr,gg,bb;if(y<horizon){let f=y/horizon;rr=8+f*10;gg=14+f*15;bb=15+f*14;if(f<.28&&((x*3+Math.floor(y/3))%79<2)){rr+=13;gg+=14;bb+=12}}else{let f=(y-horizon)/(sh-horizon);rr=18+f*23;gg=25+f*23;bb=24+f*18;let fog=Math.sin((x+y*5)*.021)*1.8;rr+=fog;gg+=fog;bb+=fog}
   if(y>=start&&y<=end){let yy=(y-start)/Math.max(1,end-start),brick=((Math.floor(x/9)+Math.floor(yy*lineH/10))%2)*.07;let light=shade+texture+brick;rr=rgb[0]*light;gg=rgb[1]*light;bb=rgb[2]*light;if((Math.floor(x/14)%2===0)&&yy>.18&&yy<.46&&Math.abs((x%34)-16)<4){rr+=15*shade;gg+=19*shade;bb+=18*shade}if(yy>.74&&Math.floor(x/8)%3===0){rr*=.77;gg*=.77;bb*=.77}}
   let fogFactor=Math.max(0,(distWall-5)/19);if(y>=start&&y<=end){rr=rr*(1-fogFactor)+18*fogFactor;gg=gg*(1-fogFactor)+25*fogFactor;bb=bb*(1-fogFactor)+25*fogFactor}data[idx]=rr;data[idx+1]=gg;data[idx+2]=bb;data[idx+3]=255
  }
 }
 const temp=document.createElement('canvas');temp.width=sw;temp.height=sh;temp.getContext('2d').putImageData(image,0,0);ctx.imageSmoothingEnabled=false;ctx.drawImage(temp,0,0,w,h);ctx.imageSmoothingEnabled=true;drawSprites(sw,sh);drawAtmosphere();
}
function hex(s){return [parseInt(s.slice(1,3),16),parseInt(s.slice(3,5),16),parseInt(s.slice(5,7),16)]}
function project(o,sw,sh){let dx=o.x-player.x,dy=o.y-player.y,forward=dx*Math.cos(player.angle)+dy*Math.sin(player.angle),side=-dx*Math.sin(player.angle)+dy*Math.cos(player.angle);if(forward<.15)return null;return{x:(.5+side/(forward*1.32))*w,y:(.49)*h,size:Math.min(h*.7,h*.56/forward),forward}}
function drawSprites(sw,sh){let sprites=[];for(const e of evidence)if(!e.found)sprites.push({...e,sprite:'evidence'});for(const it of items)sprites.push({...it,sprite:'item'});for(const p of persons)sprites.push({...p,sprite:'person'});sprites=sprites.map(o=>({o,p:project(o,sw,sh)})).filter(a=>a.p&&a.p.x>-80&&a.p.x<w+80).sort((a,b)=>b.p.forward-a.p.forward);
 for(const {o,p} of sprites){let s=p.size,xx=p.x,yy=p.y;let visible=wallAt(Math.floor(o.x),Math.floor(o.y))===0;if(!visible)continue;
  if(o.sprite==='person'){let z=Math.max(4,s*.18),head=s*.12,body=s*.38,ground=yy+s*.5;ctx.fillStyle='rgba(0,0,0,.24)';ctx.beginPath();ctx.ellipse(xx,ground,z*.9,z*.18,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=o.kind==='killer'?'#272d29':o.kind==='witness'?'#67605a':o.kind==='officer'?'#343e42':'#574f43';ctx.fillRect(xx-z/2,ground-body,z,body);ctx.fillStyle='#b9a58b';ctx.beginPath();ctx.arc(xx,ground-body-head*.58,head*.57,0,Math.PI*2);ctx.fill();ctx.fillStyle='#151a18';ctx.fillRect(xx-z*.35,ground-body*.18,z*.7,body*.18);if(p.forward<2.1){ctx.fillStyle='rgba(235,226,205,.7)';ctx.font=`${Math.max(8,Math.min(11,s*.07))}px DM Mono`;ctx.textAlign='center';ctx.fillText(o.name,xx,ground+12)}}
  else{let z=Math.max(4,s*.11),ground=yy+s*.5;ctx.fillStyle=o.sprite==='evidence'?'#c9ac70':'#a58c61';ctx.shadowColor=o.sprite==='evidence'?'#d9b866':'#9f855b';ctx.shadowBlur=Math.min(18,z*1.2);ctx.beginPath();ctx.arc(xx,ground-z*.65,z*.45,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#151a17';ctx.font=`${Math.max(7,Math.min(10,z*.6))}px DM Mono`;ctx.textAlign='center';ctx.fillText(o.sprite==='evidence'?'✣':'⌖',xx,ground-z*.49)}
 }
}
function drawAtmosphere(){// wet pavement shimmer, rain and subtle flashlight bloom
 const intensity=world.weather.includes('RAIN')?1:world.weather==='FOG'?0.55:.2;ctx.save();ctx.globalAlpha=intensity*.48;ctx.strokeStyle='#c0c6c0';ctx.lineWidth=1*pxRatio;for(let i=0;i<95;i++){let x=(Math.random()*w),y=(Math.random()*h);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3*pxRatio,y+10*pxRatio);ctx.stroke()}ctx.restore();if(player.flashlight){let g=ctx.createRadialGradient(w/2,h*.51,3,w/2,h*.52,h*.55);g.addColorStop(0,'rgba(221,220,186,.07)');g.addColorStop(.52,'rgba(211,216,197,.022)');g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.fillRect(w*.18,h*.1,w*.64,h*.8)}}
function tick(dt){let speed=(keys.ShiftLeft||keys.ShiftRight?3.2:2.05)*dt,forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),strafe=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);if(forward||strafe){let len=Math.hypot(forward,strafe);forward/=len;strafe/=len;let dx=(Math.cos(player.angle)*forward-Math.sin(player.angle)*strafe)*speed,dy=(Math.sin(player.angle)*forward+Math.cos(player.angle)*strafe)*speed;if(!collides(player.x+dx,player.y))player.x+=dx;if(!collides(player.x,player.y+dy))player.y+=dy;player.steps+=dt;if(player.steps>.7){player.steps=0;player.stress=Math.min(100,player.stress+(keys.ShiftLeft?.04:.012));if(keys.ShiftLeft)player.stamina=Math.max(12,player.stamina-.15)}}else player.stamina=Math.min(100,player.stamina+.035);
 if(mouseLook){player.angle+=mouseLook;mouseLook=0}elapsed+=dt;world.autoTick+=dt;if(world.autoTick>3){world.autoTick=0;advanceWorld(1)}updateNearby();objective()}
function updateNearby(){nearest=null;let candidates=[...items.filter(i=>!i.used),...evidence.filter(e=>!e.found),...persons];let best=1.6;for(const o of candidates){let d=dist(player,o);if(d<best){best=d;nearest=o}}if(nearest){ui.prompt.innerHTML=`<kbd>E</kbd>${nearest.prompt||`SPEAK WITH ${nearest.name.toUpperCase()}`}`;ui.prompt.classList.add('show')}else ui.prompt.classList.remove('show');let loc=nearestPlace();if(loc&&dist(player,loc)<2.5)ui.location.textContent=loc.name+(loc.kind==='chapel'?' · GROUNDS':'');else ui.location.textContent=loc.name}
function advanceWorld(n){world.minute+=n*3;while(world.minute>=1440){world.minute-=1440;world.day++;world.days++;}const hour=Math.floor(world.minute/60),min=world.minute%60;ui.clock.textContent=`${hour%12||12}:${String(min).padStart(2,'0')} ${hour>=12?'PM':'AM'}`;if(Math.random()<.008)world.weather=['COLD RAIN','FOG','LIGHT RAIN','OVERCAST'][Math.floor(Math.random()*4)];ui.weather.textContent=world.weather;
 // Simulated schedules: the important people move on roads, retain memories and react to observed attention.
 for(const p of persons){if(p.kind==='killer'){let risk=player.habits.chapel*3+player.habits.interviews*2+player.habits.forensics*2+(flags.secretFound?10:0);if(risk>18&&Math.random()<.08){p.x=12.4;p.y=6.4;p.line='The archive is not a place for the living. You should leave those pages shut.'}if(dist(p,player)<5){p.memories.push(`Saw detective near ${nearestPlace().name} on day ${world.day}.`);if(p.memories.length>12)p.memories.shift();if(Math.random()<.02){player.stress=Math.min(100,player.stress+3);say('Someone is watching from the rain.')}}}
  else if(p.kind==='witness'&&!p.met&&world.minute>330&&world.minute<1260){p.x=12.8;p.y=12.4}else if(p.kind==='officer'){p.x=18.7;p.y=18.4}}
 if(Math.random()<.012){const events=['A caller reports a broken window near Ashdown Court.','A church bell rings after midnight. No one claims to have pulled the rope.','Dispatch notes another missing-person report.','A local radio host blames the murders on outsiders.'];world.events.unshift({day:world.day,time:world.minute,text:events[Math.floor(Math.random()*events.length)]});world.events=world.events.slice(0,12)}if(world.weather==='COLD RAIN')player.stress=Math.min(100,player.stress+.012);if(player.stress>75&&Math.random()<.016){player.health=Math.max(1,player.health-.2);if(Math.random()<.2)say('A voice in the static repeats your last thought.')}
 if(world.minute%30<4)save(+(localStorage.getItem(SAVE_PREFIX+'active')||0),true)
}

(()=>{
'use strict';
const $=id=>document.getElementById(id), canvas=$('view'), ctx=canvas.getContext('2d',{alpha:false});
const ui={objective:$('objective'),progressText:$('progressText'),progressBar:$('progressBar'),location:$('locationLabel'),clock:$('clock'),weather:$('weather'),prompt:$('prompt'),toast:$('toast'),panel:$('panel'),panelTitle:$('panelTitle'),panelKicker:$('panelKicker'),panelContent:$('panelContent'),dialogue:$('dialogue'),start:$('startScreen'),ending:$('ending')};
const SAVE='gloamwood-save-';
const world={minute:22*60+17,day:17,weather:'COLD RAIN',events:[],publicTrust:54,sectPressure:0,days:1,autoTick:0,ending:null};
